UPDATE users
SET name = #{name}, email = #{email}, phone = #{phone}, city = #{city}, avatar_color = #{color}
WHERE id = #{id}

UPDATE users
SET last_lat = NULL, last_lon = NULL, last_accuracy = NULL, last_seen_at = NULL, last_address = NULL
WHERE id = #{id}

UPDATE user_settings
user_id = user_id, theme = #{s.theme}, notif_trip = #{s.notifTrip}, notif_tips = #{s.notifTips}, notif_charging = #{s.notifCharging}, notif_weekly = #{s.notifWeekly}, move_mode = #{s.moveMode}, gps_scale = #{s.gpsScale}, demo_scale = #{s.demoScale}, goal_kg = #{s.goalKg}, battery_pct = #{s.batteryPct}, active_vehicle_id = #{s.activeVehicleId}, notif_read = #{s.notifRead}, share_location = #{s.shareLocation},
WHERE user_id = #{userId}
